<?php
declare(strict_types=1);
namespace StageArtCore\Domain\Production;
final class ProductionCreditRepository{private \wpdb $db;private string $sections;private string $items;public function __construct(?\wpdb$db=null){global$wpdb;$this->db=$db??$wpdb;$this->sections=$this->db->prefix.'stageart_plugin_production_credit_sections';$this->items=$this->db->prefix.'stageart_plugin_production_credit_items';}public function sections(int$productionId,bool$releasedOnly=false):array{$sql="SELECT * FROM {$this->sections} WHERE production_id = %d";$args=[$productionId];if($releasedOnly)$sql.=' AND (release_at IS NULL OR release_at <= UTC_TIMESTAMP())';$sql.=' ORDER BY display_order ASC, id ASC';$rows=$this->db->get_results($this->db->prepare($sql,...$args),ARRAY_A)?:[];foreach($rows as&$row){$row['id']=(int)$row['id'];$row['production_id']=(int)$row['production_id'];$row['display_order']=(int)$row['display_order'];$row['items']=$this->items((int)$row['id']);}return$rows;}public function items(int$sectionId):array{$rows=$this->db->get_results($this->db->prepare("SELECT * FROM {$this->items} WHERE section_id = %d ORDER BY display_order ASC, id ASC",$sectionId),ARRAY_A)?:[];foreach($rows as&$row){$row['id']=(int)$row['id'];$row['section_id']=(int)$row['section_id'];$row['display_order']=(int)$row['display_order'];}return$rows;}public function createSection(int$productionId,string$name,?string$releaseAt=null,int$displayOrder=0):int{$now=gmdate('Y-m-d H:i:s');$this->db->insert($this->sections,['production_id'=>$productionId,'name'=>trim($name),'release_at'=>$releaseAt,'display_order'=>max(0,$displayOrder),'created_at'=>$now,'updated_at'=>$now],['%d','%s','%s','%d','%s','%s']);return(int)$this->db->insert_id;}public function updateSection(int$sectionId,int$productionId,string$name,?string$releaseAt=null,int$displayOrder=0):bool{return$this->db->update($this->sections,['name'=>trim($name),'release_at'=>$releaseAt,'display_order'=>max(0,$displayOrder),'updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$sectionId,'production_id'=>$productionId],['%s','%s','%d','%s'],['%d','%d'])!==false;}public function deleteSection(int$sectionId,int$productionId):bool{$this->db->query($this->db->prepare("DELETE FROM {$this->items} WHERE section_id = %d AND section_id IN (SELECT id FROM {$this->sections} WHERE id = %d AND production_id = %d)",$sectionId,$sectionId,$productionId));return$this->db->delete($this->sections,['id'=>$sectionId,'production_id'=>$productionId],['%d','%d'])!==false;}public function createItem(int$sectionId,string$name,?string$url=null,int$displayOrder=0):int{$now=gmdate('Y-m-d H:i:s');$url=$url!==null&&trim($url)!==''?esc_url_raw(trim($url)):null;$this->db->insert($this->items,['section_id'=>$sectionId,'name'=>trim($name),'url'=>$url,'display_order'=>max(0,$displayOrder),'created_at'=>$now,'updated_at'=>$now],['%d','%s','%s','%d','%s','%s']);return(int)$this->db->insert_id;}public function updateItem(int$itemId,int$sectionId,string$name,?string$url=null,int$displayOrder=0):bool{$url=$url!==null&&trim($url)!==''?esc_url_raw(trim($url)):null;return$this->db->update($this->items,['name'=>trim($name),'url'=>$url,'display_order'=>max(0,$displayOrder),'updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$itemId,'section_id'=>$sectionId],['%s','%s','%d','%s'],['%d','%d'])!==false;}public function deleteItem(int$itemId,int$sectionId):bool{return$this->db->delete($this->items,['id'=>$itemId,'section_id'=>$sectionId],['%d','%d'])!==false;}public function reorderSections(int$productionId,array$orderedIds):void{$this->reorder($this->sections,'production_id',$productionId,$orderedIds);}public function reorderItems(int$sectionId,array$orderedIds):void{$this->reorder($this->items,'section_id',$sectionId,$orderedIds);}private function reorder(string$table,string$parentColumn,int$parentId,array$orderedIds):void{foreach(array_values($orderedIds)as$order=>$id)$this->db->query($this->db->prepare("UPDATE {$table} SET display_order = %d, updated_at = %s WHERE id = %d AND {$parentColumn} = %d",$order,gmdate('Y-m-d H:i:s'),(int)$id,$parentId));}}
